import{_ as t,c as o,o as d,b2 as r}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"部门管理（系统管理）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-dept-management-design.md","filePath":"superpowers/specs/2026-05-08-dept-management-design.md"}'),s={name:"superpowers/specs/2026-05-08-dept-management-design.md"};function c(n,e,a,l,i,g){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="部门管理-系统管理-设计说明" tabindex="-1">部门管理（系统管理）设计说明 <a class="header-anchor vp-link" href="#部门管理-系统管理-设计说明" aria-label="Permalink to &quot;部门管理（系统管理）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与补充确认：<strong>list 采用方案二（嵌套树）</strong>、<strong>迁移仅 <code>sys_dept</code></strong>、<strong>删除用户占用校验延后至用户表就绪</strong>）<br><strong>依据</strong>：<code>原始需求/系统管理/部门管理-原始需求.md</code>、既有 <code>quick-ui/src/api/system/dept.js</code></p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：原始需求要求树形展示、字段与筛选、增删改查；前端已存在与若依风格接近的部门 API 封装；后端当前以占位迁移与认证为主，<strong>尚无部门实体与接口</strong>。</li><li><strong>目标</strong>：交付<strong>可联调闭环</strong>：Flyway 建 <strong><code>sys_dept</code></strong>、后端 CRUD + 树形列表/下拉树、前端部门管理页；删除规则：<strong>存在子部门则禁止</strong>；状态与字典 <strong><code>sys_normal_disable</code>（0 正常 / 1 停用）</strong> 一致；负责人为<strong>文本</strong>。</li><li><strong>非目标（本迭代）</strong>：在删除接口中校验「部门下是否仍有用户」——<strong>延后</strong>至 <strong><code>sys_user</code>（或等价表）含 <code>dept_id</code> 且迁移就绪</strong> 后，在同一删除流程中增加计数校验（见 §7）。</li></ul><hr><h2 id="_2-澄清结论汇总" tabindex="-1">2. 澄清结论汇总 <a class="header-anchor vp-link" href="#_2-澄清结论汇总" aria-label="Permalink to &quot;2. 澄清结论汇总&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>结论</th></tr></thead><tbody><tr><td>交付边界</td><td>前后端打通的最小可演示闭环</td></tr><tr><td>API 路径</td><td>与 <code>dept.js</code> 一致：<code>/system/dept/list</code>、<code>treeselect</code>、<code>GET/POST/PUT/DELETE</code></td></tr><tr><td>列表形态</td><td><strong><code>GET /system/dept/list</code> 返回嵌套树</strong>（根节点数组，节点含 <code>children</code>）；<strong>不</strong>依赖前端 <code>handleTree</code> 从扁平转树</td></tr><tr><td>删除（子部门）</td><td>存在子部门 → <strong>禁止删除</strong>，明确错误提示</td></tr><tr><td>删除（用户）</td><td><strong>本迭代不实现</strong>；用户表就绪后补齐（§7）</td></tr><tr><td>负责人</td><td>字符串</td></tr><tr><td>状态</td><td>与系统用户一致的字典取值</td></tr></tbody></table></div><hr><h2 id="_3-数据模型-sys-dept" tabindex="-1">3. 数据模型（<code>sys_dept</code>） <a class="header-anchor vp-link" href="#_3-数据模型-sys-dept" aria-label="Permalink to &quot;3. 数据模型（`sys_dept`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>dept_id</code></td><td>主键，自增或雪花（与项目 ID 策略一致）</td></tr><tr><td><code>parent_id</code></td><td>上级部门 ID；<strong>顶级为 <code>-1</code></strong>（与原始需求一致）</td></tr><tr><td><code>dept_name</code></td><td>部门名称</td></tr><tr><td><code>order_num</code></td><td>显示排序（同级）</td></tr><tr><td><code>leader</code></td><td>负责人（文本）</td></tr><tr><td><code>phone</code></td><td>联系电话</td></tr><tr><td><code>email</code></td><td>邮箱</td></tr><tr><td><code>status</code></td><td>与 <strong><code>sys_normal_disable</code></strong> 一致（建议 <code>char(1)</code>：<code>0</code>/<code>1</code>）</td></tr><tr><td><code>remark</code></td><td>备注</td></tr><tr><td><code>del_flag</code></td><td>逻辑删除标记（与项目惯例对齐；若首版无统一惯例则采用 <code>0</code> 存在 <code>2</code> 删除）</td></tr><tr><td>审计字段</td><td><code>create_by</code>、<code>create_time</code>、<code>update_by</code>、<code>update_time</code>（与 quickboot-web 后续模块对齐）</td></tr></tbody></table></div><p><strong>索引建议</strong>：<code>parent_id</code>、<code>del_flag</code> 组合查询；必要时 <code>dept_name</code> 前缀索引视数据量再定。</p><p><strong>说明</strong>：不在本迁移中创建 <strong><code>sys_user</code></strong>；删除接口<strong>仅</strong>校验子部门。</p><hr><h2 id="_4-api-契约-对齐-dept-js-载荷形状与-r-data-一致" tabindex="-1">4. API 契约（对齐 <code>dept.js</code>，载荷形状与 <code>R.data</code> 一致） <a class="header-anchor vp-link" href="#_4-api-契约-对齐-dept-js-载荷形状与-r-data-一致" aria-label="Permalink to &quot;4. API 契约（对齐 `dept.js`，载荷形状与 `R.data` 一致）&quot;">​</a></h2><p>统一响应：<code>code</code> / <code>msg</code> / <code>data</code>（见 <code>io.github.genkidoudou.common.api.R</code>）。前端 <code>request</code> 拦截器 resolve 为<strong>整段</strong> <code>res.data</code>，业务页取 <strong><code>data</code> 字段</strong>作为载荷。</p><h3 id="_4-1-get-system-dept-list" tabindex="-1">4.1 <code>GET /system/dept/list</code> <a class="header-anchor vp-link" href="#_4-1-get-system-dept-list" aria-label="Permalink to &quot;4.1 `GET /system/dept/list`&quot;">​</a></h3><ul><li><p><strong>Query</strong>（与需求一致，名称与前端表单字段对齐即可）：<code>deptName</code>、<code>leader</code>、<code>status</code>（均可选）；无附加参数时表示「无筛选」。</p></li><li><p><strong>成功 <code>data</code></strong>：<strong><code>List&lt;DeptNode&gt;</code></strong>，仅<strong>根节点</strong>出现在顶层数组；每个节点：</p><ul><li>业务字段与表一致（含 <code>deptId</code>、<code>parentId</code>、<code>deptName</code>、<code>orderNum</code>、<code>leader</code>、<code>phone</code>、<code>email</code>、<code>status</code>、<code>remark</code> 等）；</li><li><strong><code>children</code></strong>：<code>List&lt;DeptNode&gt;</code>，无子则为<strong>空数组</strong>或 <strong><code>null</code></strong>（实现阶段二选一并在本文档与前端约定一致，<strong>推荐空数组</strong>便于表格）。</li></ul></li></ul><p><strong>筛选 + 树形（方案二）语义（须实现一致）</strong>：</p><ul><li><strong>无筛选条件</strong>：返回完整部门树（所有未删除节点，根 <code>parent_id = -1</code>）。</li><li><strong>有任一筛选条件</strong>：返回<strong>剪枝后的森林</strong>——仅包含「自身或子孙匹配筛选条件的节点」，且对每个命中节点<strong>保留从根到该节点的祖先链</strong>，以便树上仍可见路径；不匹配且不在任何命中路径上的分支<strong>不出现</strong>。 <ul><li>若整棵树无匹配：<code>data</code> 为<strong>空数组</strong>。</li></ul></li></ul><blockquote><p><strong>与若依差异说明</strong>：常见若依 <code>list</code> 为扁平行；本设计为<strong>嵌套树</strong>，部门管理页<strong>直接</strong> <code>:data=&quot;data&quot;</code> 绑定 <code>el-table</code> 的 <code>tree-props</code>，<strong>不再</strong>假定 <code>rows</code> 扁平。其它若仍消费扁平 <code>list</code> 的代码（若有）需在实现时改为使用 <code>treeselect</code> 或单独接口。</p></blockquote><h3 id="_4-2-get-system-dept-treeselect" tabindex="-1">4.2 <code>GET /system/dept/treeselect</code> <a class="header-anchor vp-link" href="#_4-2-get-system-dept-treeselect" aria-label="Permalink to &quot;4.2 `GET /system/dept/treeselect`&quot;">​</a></h3><ul><li>用于表单「上级部门」等树选择；<strong>成功 <code>data</code></strong>：树形结构，节点至少含 <strong><code>id</code></strong>（=<code>dept_id</code>）、<strong><code>label</code></strong>（=<code>dept_name</code>）、<strong><code>children</code></strong>（规则同 4.1）。</li><li>可带与列表一致的筛选 query；<strong>默认</strong>实现可与 <code>list</code> 共用建树逻辑（是否允许筛选由产品决定，<strong>首版建议忽略筛选、始终全量树</strong>，避免下拉树与列表搜索耦合）。</li></ul><h3 id="_4-3-get-system-dept-deptid" tabindex="-1">4.3 <code>GET /system/dept/{deptId}</code> <a class="header-anchor vp-link" href="#_4-3-get-system-dept-deptid" aria-label="Permalink to &quot;4.3 `GET /system/dept/{deptId}`&quot;">​</a></h3><ul><li><strong>成功 <code>data</code></strong>：单条部门 VO（不必含 <code>children</code>，或含直接子节点——实现择一，<strong>推荐扁平单条 + <code>parentId</code> 便于编辑回显</strong>）。</li></ul><h3 id="_4-4-post-system-dept" tabindex="-1">4.4 <code>POST /system/dept</code> <a class="header-anchor vp-link" href="#_4-4-post-system-dept" aria-label="Permalink to &quot;4.4 `POST /system/dept`&quot;">​</a></h3><ul><li>Body：新增实体（无 <code>deptId</code> 或忽略）；<code>parentId</code> 允许 <code>-1</code> 表示顶级。</li></ul><h3 id="_4-5-put-system-dept" tabindex="-1">4.5 <code>PUT /system/dept</code> <a class="header-anchor vp-link" href="#_4-5-put-system-dept" aria-label="Permalink to &quot;4.5 `PUT /system/dept`&quot;">​</a></h3><ul><li>Body：含 <code>deptId</code> 及可更新字段。</li></ul><h3 id="_4-6-delete-system-dept-deptid" tabindex="-1">4.6 <code>DELETE /system/dept/{deptId}</code> <a class="header-anchor vp-link" href="#_4-6-delete-system-dept-deptid" aria-label="Permalink to &quot;4.6 `DELETE /system/dept/{deptId}`&quot;">​</a></h3><ul><li><strong>校验</strong>：存在 <strong><code>del_flag</code> 正常的子部门</strong> → 返回业务错误（<code>code != 200</code>），<code>msg</code> 可读。</li><li><strong>不校验</strong>用户占用（延后，见 §7）。</li></ul><p><strong>写操作共性校验</strong>：</p><ul><li><code>parent_id</code> 指向的父节点须存在且未删除；<strong>不可</strong>指向自身。</li><li><strong>改父级</strong>：不可导致环（不可将节点挪到其子孙之下）；可用「收集当前节点及其子孙 id 集，父 id 不得落在该集合」实现。</li><li>字段格式：邮箱、手机可选校验，与项目全局校验方式一致。</li></ul><hr><h2 id="_5-前端-单页-筛选-树表" tabindex="-1">5. 前端（单页：筛选 + 树表） <a class="header-anchor vp-link" href="#_5-前端-单页-筛选-树表" aria-label="Permalink to &quot;5. 前端（单页：筛选 + 树表）&quot;">​</a></h2><ul><li><strong>路由/菜单</strong>：与现有 <code>system/user</code> 等页面同构注册；权限标识在实现计划中列清单（如 <code>system:dept:list</code> 等）。</li><li><strong>搜索区</strong>：<code>deptName</code>、<code>leader</code>、<code>status</code>（<code>useDict(&#39;sys_normal_disable&#39;)</code>）。</li><li><strong>表格</strong>：<code>el-table</code> + <code>row-key=&quot;deptId&quot;</code> + <code>tree-props=&quot;{ children: &#39;children&#39;, hasChildren: &#39;hasChildren&#39; }&quot;</code>（若无懒加载可不设 <code>hasChildren</code>）；数据源为 <strong><code>listDept</code> 返回的 <code>data</code> 根数组</strong>。</li><li><strong>操作</strong>：新增、修改、删除、查看（只读弹窗或抽屉）；上级部门选择器数据源 <strong><code>listTreeDept</code></strong>（<code>treeselect</code>）。</li><li><strong>删除</strong>：二次确认后调 <code>delDept</code>；展示后端返回的 <code>msg</code>。</li></ul><hr><h2 id="_6-错误处理与安全" tabindex="-1">6. 错误处理与安全 <a class="header-anchor vp-link" href="#_6-错误处理与安全" aria-label="Permalink to &quot;6. 错误处理与安全&quot;">​</a></h2><ul><li>业务失败统一 <strong><code>R.error(code, msg)</code></strong>；HTTP 状态码与项目全局约定一致（通常为 200 + body <code>code</code>）。</li><li>接口需登录态（Sa-Token）；权限与路由 meta 对齐预留。</li></ul><hr><h2 id="_7-延后项-用户占用删除校验" tabindex="-1">7. 延后项：用户占用删除校验 <a class="header-anchor vp-link" href="#_7-延后项-用户占用删除校验" aria-label="Permalink to &quot;7. 延后项：用户占用删除校验&quot;">​</a></h2><p><strong>触发条件</strong>：库中存在用户表（如 <strong><code>sys_user</code></strong>），且含 <strong><code>dept_id</code></strong>（或等价外键），并与部门模块同属一库、可统计。</p><p><strong>行为</strong>：在 <code>DELETE /system/dept/{id}</code> 中，在子部门校验<strong>之后</strong>（或之前均可，但顺序不影响结果）增加：<br><code>count(*) where dept_id = ? and del_flag = 正常</code> <strong>&gt; 0</strong> 则 <strong>禁止删除</strong> 并返回明确文案。</p><p><strong>本迭代</strong>：不建用户表、不实现该校验；在 Service 层可预留 <strong><code>UserDeptGuard</code></strong> 接口或 TODO 注释，避免遗忘。</p><hr><h2 id="_8-测试建议" tabindex="-1">8. 测试建议 <a class="header-anchor vp-link" href="#_8-测试建议" aria-label="Permalink to &quot;8. 测试建议&quot;">​</a></h2><ul><li><strong>后端</strong>：删除存在子部门失败；改父级成环失败；<code>parent_id = -1</code> 新增根；<code>list</code> 无筛选为全树；带 <code>deptName</code> 筛选为剪枝树且祖先保留。</li><li><strong>前端</strong>：手工联调增删改查与筛选；字典与表格展示一致。</li></ul><hr><h2 id="_9-实现计划入口" tabindex="-1">9. 实现计划入口 <a class="header-anchor vp-link" href="#_9-实现计划入口" aria-label="Permalink to &quot;9. 实现计划入口&quot;">​</a></h2><p>实现前另起 <strong><code>writing-plans</code></strong> 产出分任务计划（含 Flyway 版本号、Controller 包路径、前端路由路径与菜单 SQL 若需要）。</p><hr><h2 id="_10-自审记录-定稿前已处理" tabindex="-1">10. 自审记录（定稿前已处理） <a class="header-anchor vp-link" href="#_10-自审记录-定稿前已处理" aria-label="Permalink to &quot;10. 自审记录（定稿前已处理）&quot;">​</a></h2><ul><li><strong>占位</strong>：无 TBD。</li><li><strong>一致性</strong>：方案二与「仅 <code>sys_dept</code>」并存；用户删除约束在 §7 明确延后，与早期「有用户则禁止删」的意图在<strong>用户表就绪后</strong>对齐。</li><li><strong>范围</strong>：单变更内可交付；用户模块非本设计范围。</li><li><strong>歧义</strong>：<code>children</code> 空形态已推荐空数组；<code>treeselect</code> 首版建议全量树，与 §4.2 一致。</li></ul>',53)])])}const u=t(s,[["render",c]]);export{h as __pageData,u as default};
